            v(3,1) = pay*v(1,1) + wpy*v(1,0)
            v(4,1) = paz*v(1,1) + wpz*v(1,0)
            v(22,1) = qcx*v(1,1) + wqx*v(1,0)
            v(39,1) = qcy*v(1,1) + wqy*v(1,0)
            v(62,1) = qcz*v(1,1) + wqz*v(1,0)
